import{_ as a,o as n,c as d,aa as o,j as t}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/academy/img/podepsani-dne/02.webp",s="/buildary-help-preview/media/cs/diary/denniprotokol2.png",r="/buildary-help-preview/academy/img/vystupy-deniku/02.webp",i="/buildary-help-preview/media/cs/diary/stahovani_dat_z_deniku.png",b=JSON.parse('{"title":"Tisk a export deníku","description":"","frontmatter":{"title":"Tisk a export deníku","wiki":"cs:diary:download"},"headers":[],"relativePath":"diary/download.md","filePath":"diary/download.md","lastUpdated":1794209661000}'),p={name:"diary/download.md"};function h(u,e,k,c,y,m){return n(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="tisk-a-export-deniku" tabindex="-1">Tisk a export deníku <a class="header-anchor" href="#tisk-a-export-deniku" aria-label="Permalink to &quot;Tisk a export deníku&quot;">​</a></h1><p>Deník si prohlédnete jako PDF, vytisknete ho a stáhnete – celý nebo za zvolené období, s podpisy pro archiv nebo jako pracovní kopii, případně jako data do Excelu.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/vystupy-deniku">Najít zápis, vytisknout nebo stáhnout deník</a> v Akademii.</p><h2 id="denni-protokol" tabindex="-1">Denní protokol <a class="header-anchor" href="#denni-protokol" aria-label="Permalink to &quot;Denní protokol&quot;">​</a></h2><p><strong>Denní protokol</strong> je PDF se záznamy jednoho dne. Otevřete ho tlačítkem <strong>Náhled PDF</strong> nad denními záznamy. Stejné volby jsou v <strong>Dalších volbách</strong>: <strong>Náhled denního záznamu</strong> a <strong>Stažení denního záznamu</strong>. V náhledu ho můžete stáhnout nebo vytisknout.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Náhled Denního protokolu v PDF s tlačítky pro stažení a tisk" loading="lazy"></figure><ul><li>Obsah odpovídá dennímu záznamu na obrazovce a je rozdělený do stejných sekcí. Když má sekce málo údajů, vypíše se do více sloupců, aby se ušetřilo místo.</li><li><strong>Další záznamy</strong> jsou v protokolu vypsané a jejich vlastní PDF (pokud jsou vytvořená a podepsaná) jsou k Dennímu protokolu automaticky přiložená.</li><li>Obrázky z denního záznamu jsou vložené přímo do PDF, ostatní soubory jsou jeho přílohy.</li></ul><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Denní protokol v Adobe Acrobat Readeru s otevřeným panelem příloh" loading="lazy"></figure><div class="tip custom-block"><p class="custom-block-title">Přílohy PDF</p><p>Přílohy PDF zobrazí například Adobe Acrobat Reader: v levém panelu klikněte na ikonu sponky.</p></div>',9),t("div",{class:"video"},[t("iframe",{src:"https://www.youtube-nocookie.com/embed/s7FwVxrRias",title:"Video: Denní protokol",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),o('<h2 id="nahled-deniku" tabindex="-1">Náhled deníku <a class="header-anchor" href="#nahled-deniku" aria-label="Permalink to &quot;Náhled deníku&quot;">​</a></h2><p>V levém panelu otevřete <strong>Náhled deníku</strong>. Deník se zobrazí jako PDF po jednotlivých dnech, mezi dny přecházíte šipkami nebo kalendářem. Tlačítkem <strong>Úvodní list deníku</strong> zobrazíte titulní listy. Každý den odtud stáhnete nebo vytisknete ikonami nad dokumentem.</p><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Náhled deníku s PDF jednoho dne a tlačítky Denní záznamy, Náhled deníku a Úvodní list deníku" loading="lazy"></figure><h2 id="vyhledat-v-deniku" tabindex="-1">Vyhledat v deníku <a class="header-anchor" href="#vyhledat-v-deniku" aria-label="Permalink to &quot;Vyhledat v deníku&quot;">​</a></h2><p>Tlačítkem <strong>Vyhledávání</strong> v hlavičce deníku prohledáte celý deník. Výsledky ukazují dny a záznamy, kde se hledaný výraz vyskytuje.</p><h2 id="stahnout-cely-denik" tabindex="-1">Stáhnout celý deník <a class="header-anchor" href="#stahnout-cely-denik" aria-label="Permalink to &quot;Stáhnout celý deník&quot;">​</a></h2><p>Menu <strong>Exporty</strong> v hlavičce deníku nabízí:</p><table tabindex="0"><thead><tr><th>Volba</th><th>Co dostanete</th><th>K čemu</th></tr></thead><tbody><tr><td><strong>Stažení oficiální verze deníku</strong></td><td>ZIP: titulní listy deníku, PDF každého elektronicky podepsaného dne a složka s přílohami</td><td>archiv a předání deníku – soubory obsahují elektronické podpisy</td></tr><tr><td><strong>Stažení pracovní verze deníku</strong></td><td>jedno PDF: titulní listy a záznamy všech dnů, podepsaných i nepodepsaných</td><td>prohlížení, hledání v textu a tisk – <strong>neobsahuje elektronické podpisy</strong></td></tr><tr><td><strong>Stažení příloh</strong></td><td>ZIP se všemi přílohami deníku</td><td>přílohy pohromadě, bez procházení jednotlivých dnů</td></tr><tr><td><strong>Export dat do Excelu</strong></td><td>soubor XLS, každá sekce na samostatném listu, data seřazená chronologicky</td><td>další zpracování dat</td></tr></tbody></table><figure class="shot" style="--w:420px;"><img src="'+i+'" alt="Menu Exporty s volbami pro stažení oficiální a pracovní verze deníku, příloh a exportem do Excelu" loading="lazy"></figure><p>U každé volby můžete zadat období. Když ho nevyplníte, stáhne se celý deník.</p><div class="tip custom-block"><p class="custom-block-title">Velké deníky</p><p>U velkého deníku nebo pomalého připojení se export nemusí stihnout v časovém limitu. Stahujte pak po částech, například po měsících.</p></div><p>Souhrny dat za období (osoby, stroje, materiály, počasí) najdete v <a href="/buildary-help-preview/diary/reports">Přehledech</a>.</p>',12)])])}const g=a(p,[["render",h]]);export{b as __pageData,g as default};
